#include "event_bus.hpp"

#include <cassert>
#include <iostream>

int main() {
    {
        EventLog log(100);
        EventBus bus(log);
        std::vector<std::pair<std::string, std::string>> items = {
            {"orders", "o1"}, {"payments", "p1"}
        };
        int result = bus.publishBatch(items);
        assert(result == 0); /* no subscribers, but the batch is valid */
        assert(log.size() == 2);
    }
    {
        EventLog log(100);
        EventBus bus(log);
        std::vector<std::pair<std::string, std::string>> items = {
            {"orders", "o1"}, {"", "bad"}
        };
        int result = bus.publishBatch(items);
        assert(result == -1);
        assert(log.size() == 0);
    }
    std::cout << "PASS" << std::endl;
    return 0;
}

