#pragma once

#include <functional>
#include <string>
#include <unordered_map>
#include <utility>
#include <vector>

#include "event.hpp"
#include "event_log.hpp"

class EventBus {
public:
    using Callback = std::function<void(const Event&)>;

    explicit EventBus(EventLog& log) : log_(log) {}

    int subscribe(const std::string& topic, Callback cb) {
        int id = next_id_++;
        subscribers_[id] = std::make_pair(topic, std::move(cb));
        return id;
    }

    void unsubscribe(int subscription_id) { subscribers_.erase(subscription_id); }

    int publish(const std::string& topic, const std::string& payload) {
        if (topic.empty()) {
            return -1;
        }
        Event event{next_seq_++, topic, payload};
        log_.record(event);
        int invoked = 0;
        for (const auto& entry : subscribers_) {
            if (entry.second.first == topic) {
                entry.second.second(event);
                invoked++;
            }
        }
        return invoked;
    }

    /*
     * Publishes a batch of (topic, payload) pairs atomically: every
     * topic in the batch must be non-empty BEFORE any of them are
     * published - one bad (empty) topic anywhere in the batch means
     * NOTHING in the batch gets logged or delivered. Returns the total
     * number of subscriber callbacks invoked across the whole batch on
     * success, or -1 if the batch was rejected.
     */
    int publishBatch(const std::vector<std::pair<std::string, std::string>>& items) {
        if (items.empty()) {
            return -1;
        }
        for (const auto& item : items) {
            if (item.first.empty()) {
                return -1;
            }
        }
        int total = 0;
        for (const auto& item : items) {
            int invoked = publish(item.first, item.second);
            total += invoked;
        }
        return total;
    }

private:
    EventLog& log_;
    std::unordered_map<int, std::pair<std::string, Callback>> subscribers_;
    int next_id_ = 1;
    long next_seq_ = 1;
};

